function pluck(arr){
  if(arr.length === 0 || arr.every(node => node % 2 !== 0)) return [];

  let smallestValue = Infinity;
  let smallestIndex = -1;

  for(let i = 0; i < arr.length; i++) {
    if(arr[i] % 2 === 0 && arr[i] < smallestValue) {
      smallestValue = arr[i];
      smallestIndex = i;
    }
  }

  return [smallestValue, smallestIndex];
}

function maxAverageOfPath(cost) {
  const N = cost.length;
  const dp = Array.from({ length: N }, () => Array(N).fill(0));

  // Initialize the first row and first column
  for (let i = 0; i < N; i++) {
    dp[0][i] = cost[0][i];
    dp[i][0] = cost[i][0];
  }

  // Fill the dp table
  for (let i = 1; i < N; i++) {
    for (let j = 1; j < N; j++) {
      dp[i][j] = Math.max(cost[i][j] + dp[i-1][j], cost[i][j] + dp[i][j-1]);
    }
  }

  // Calculate the maximum average path
  let maxAverage = 0;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      maxAverage = Math.max(maxAverage, dp[i][j]);
    }
  }

  return maxAverage / (N * N);
}

function maxAverageOfPath(cost) {
    const N = cost.length;
    // Initialize the DP table with zeros
    const dp = Array.from({ length: N }, () => Array(N).fill(0));

    // Fill the DP table
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (i === 0 && j === 0) {
                dp[i][j] = cost[i][j];
            } else if (i === 0) {
                dp[i][j] = dp[i][j - 1] + cost[i][j];
            } else if (j === 0) {
                dp[i][j] = dp[i - 1][j] + cost[i][j];
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j];
            }
        }
    }

    // The maximum average is the value in the bottom-right corner of the DP table
    return dp[N - 1][N - 1] / (N * N);
}

