function comb_sort(nums) {
    let gap = nums.length;
    let swapped = true;

    while (gap > 1 || swapped) {
        if (gap > 1) {
            gap = Math.floor(gap / 1.3);
        }

        swapped = false;

        for (let i = 0; i < nums.length - gap; i++) {
            if (nums[i] > nums[i + gap]) {
                [nums[i], nums[i + gap]] = [nums[i + gap], nums[i]];
                swapped = true;
            }
        }
    }

    return nums;
}

function int_to_mini_roman(number){
  const romanNumerals = [
    { value: 1000, numeral: 'm' },
    { value: 900, numeral: 'cm' },
    { value: 500, numeral: 'd' },
    { value: 400, numeral: 'cd' },
    { value: 100, numeral: 'c' },
