}

function sum_of_digits(nums) {
  let totalSum = 0;

  // Loop through each number in the array
  for (let i = 0; i < nums.length; i++) {
    // Convert the number to a string to easily access each digit
    let numStr = nums[i].toString();

    // Loop through each digit in the number string
    for (let j = 0; j < numStr.length; j++) {
      // Convert the digit back to an integer and add it to the total sum
      totalSum += parseInt(numStr[j], 10);
    }
  }

  // Return the total sum of the digits of each number
  return totalSum;
}

