function combinations_colors(l, n) {
  const result = [];
  const generateCombinations = (index, currentCombination) => {
    if (currentCombination.length === n) {
      result.push(currentCombination.slice());
      return;
    }
    for (let i = index; i < l; i++) {
      generateCombinations(i, currentCombination.concat(l[i]));
    }
  };
  generateCombinations(0, []);
  return result;
}

function combinations_colors(l, n) {
  const result = [];
  const currentCombination = [];

  function backtrack(startIndex) {
    if (currentCombination.length === n) {
      result.push([...currentCombination]);
      return;
    }

    for (let i = startIndex; i < l; i++) {
      currentCombination.push(l[i]);
      backtrack(i);
      currentCombination.pop();
    }
  }

  backtrack(0);
  return result;
}

