function search(arr) {
  let left = 0;
  let right = arr.length - 1;

  while (left < right) {
    let mid = Math.floor((left + right) / 2);

    if (arr[mid] === arr[mid + 1]) {
      left = mid + 2;
    } else {
      right = mid;
    }
  }

  return arr[left];
}

