}

function are_equivalent(num1, num2) {
  // Calculate the sum of divisors for num1
  let sum1 = 0;
  for (let i = 1; i <= num1; i++) {
    if (num1 % i === 0) {
      sum1 += i;
    }
  }

  // Calculate the sum of divisors for num2
  let sum2 = 0;
  for (let i = 1; i <= num2; i++) {
    if (num2 % i === 0) {
      sum2 += i;
    }
  }

  // Check if the sums are the same
  return sum1 === sum2;
}
